package cli

import (
	"encoding/json"
	"strings"
)

// parseListFlag converts a CLI flag value into a slice value for a JSON request
// body. It accepts either a JSON array (e.g. `["SMARTLEAD","INSTANTLY"]`) or a
// plain comma-separated list (e.g. `SMARTLEAD,INSTANTLY`); a single bare token
// becomes a one-element list. This lets array-valued body flags take friendly
// CSV input instead of forcing the caller to hand-write JSON.
func parseListFlag(raw string) any {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return []string{}
	}
	if strings.HasPrefix(raw, "[") {
		var arr []any
		if err := json.Unmarshal([]byte(raw), &arr); err == nil {
			return arr
		}
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := strings.TrimSpace(p); s != "" {
			out = append(out, s)
		}
	}
	return out
}
